export interface ParsedVocabWord {
  id: string;
  word: string;
  pos: string;
  meaning: string;
  synonyms: string[];
  antonyms: string[];
  additional?: string;
  additionalGroups?: Array<{ theme: string; terms: string }>;
  example?: string;
  mnemonic?: string;
}

export interface ParsedVocabDocument {
  headerTitle: string;
  words: ParsedVocabWord[];
  rawMarkdown: string;
  truncationNote?: string;
}

/**
 * Robustly parses stylized Markdown (or plain text) generated by Gemini
 * into structured vocabulary words and themes.
 */
export function parseVocabMarkdown(rawMarkdown: string): ParsedVocabDocument {
  if (!rawMarkdown || !rawMarkdown.trim()) {
    return {
      headerTitle: 'Core Vocabularies & Additional Words',
      words: [],
      rawMarkdown: '',
    };
  }

  const cleanText = rawMarkdown
    .replace(/^```markdown\s*/gi, '')
    .replace(/^```\s*/gi, '')
    .replace(/\s*```$/gi, '')
    .trim();

  const lines = cleanText.split('\n');
  const words: ParsedVocabWord[] = [];
  let headerTitle = 'Core Vocabularies & Additional Words';
  let truncationNote: string | undefined = undefined;

  let currentWord: Partial<ParsedVocabWord> | null = null;
  let currentField: 'meaning' | 'synonyms' | 'antonyms' | 'additional' | 'example' | null = null;
  const additionalLines: string[] = [];

  const finalizeCurrentWord = () => {
    if (currentWord && currentWord.word) {
      if (additionalLines.length > 0) {
        currentWord.additional = additionalLines.join('\n').trim();
        // Parse individual theme groups like "(weak): Feeble, Frail"
        const groups: Array<{ theme: string; terms: string }> = [];
        for (const line of additionalLines) {
          const match = line.match(/^\s*\(([^)]+)\)\s*:\s*(.+)$/);
          if (match) {
            groups.push({ theme: match[1].trim(), terms: match[2].trim() });
          } else if (line.trim()) {
            groups.push({ theme: 'Related', terms: line.trim() });
          }
        }
        currentWord.additionalGroups = groups;
      }

      words.push({
        id: Math.random().toString(36).substring(2, 9),
        word: currentWord.word.trim(),
        pos: currentWord.pos?.trim() || 'Noun',
        meaning: currentWord.meaning?.trim() || '',
        synonyms: currentWord.synonyms || [],
        antonyms: currentWord.antonyms || [],
        additional: currentWord.additional || '',
        additionalGroups: currentWord.additionalGroups || [],
        example: currentWord.example?.trim() || '',
        mnemonic: currentWord.mnemonic?.trim() || '',
      });
    }
    currentWord = null;
    currentField = null;
    additionalLines.length = 0;
  };

  for (let i = 0; i < lines.length; i++) {
    const rawLine = lines[i];
    const trimmed = rawLine.trim();

    if (!trimmed) continue;

    // Check for title header e.g. "#### **Core Vocabularies & Additional Words**"
    if (/^#+\s*(\*\*)?Core Vocabularies/i.test(trimmed) || /^Core Vocabularies/i.test(trimmed)) {
      headerTitle = trimmed.replace(/^[#*\s]+|[#*\s]+$/g, '').trim();
      continue;
    }

    // Check for truncation fallback notice
    if (/transcript appears to be truncated/i.test(trimmed)) {
      truncationNote = trimmed;
      continue;
    }

    // Match Word Header: e.g. "* **Debilitating (Adjective)**" or "**Debilitating (Adjective)**" or "Debilitating (Adjective)"
    const wordHeaderMatch = trimmed.match(
      /^(?:\*|\-)?\s*(?:\*\*)?([A-Za-z\s\-']+?)\s*\(([^)]+)\)(?:\*\*)?\s*$/
    );

    // Ensure it's not a field like (weak): ... or Meaning: ...
    const isFieldStart = /^(?:\*|\-)?\s*(?:\*\*)?(Meaning|Synonyms|Antonyms|Additional|Example):/i.test(trimmed);

    if (wordHeaderMatch && !isFieldStart && !/^\s*\([^)]+\):/.test(trimmed)) {
      finalizeCurrentWord();
      const detectedWord = wordHeaderMatch[1].replace(/\*\*/g, '').trim();
      const detectedPos = wordHeaderMatch[2].replace(/\*\*/g, '').trim();

      currentWord = {
        word: detectedWord,
        pos: detectedPos,
        synonyms: [],
        antonyms: [],
      };
      continue;
    }

    // If we have an active word, match sub-fields
    if (currentWord) {
      // Meaning
      const meaningMatch = trimmed.match(/^(?:\*|\-)?\s*(?:\*\*)?Meaning(?:\*\*)?\s*:\s*(.+)$/i);
      if (meaningMatch) {
        currentField = 'meaning';
        currentWord.meaning = meaningMatch[1].replace(/^\*\*|\*\*$/g, '').trim();
        continue;
      }

      // Synonyms
      const synonymsMatch = trimmed.match(/^(?:\*|\-)?\s*(?:\*\*)?Synonyms(?:\*\*)?\s*:\s*(.*)$/i);
      if (synonymsMatch) {
        currentField = 'synonyms';
        const synStr = synonymsMatch[1].replace(/^\*\*|\*\*$/g, '').trim();
        currentWord.synonyms = synStr
          ? synStr.split(',').map((s) => s.trim().replace(/^\*\*|\*\*$/g, '')).filter(Boolean)
          : [];
        continue;
      }

      // Antonyms
      const antonymsMatch = trimmed.match(/^(?:\*|\-)?\s*(?:\*\*)?Antonyms(?:\*\*)?\s*:\s*(.*)$/i);
      if (antonymsMatch) {
        currentField = 'antonyms';
        const antStr = antonymsMatch[1].replace(/^\*\*|\*\*$/g, '').trim();
        currentWord.antonyms = antStr
          ? antStr.split(',').map((s) => s.trim().replace(/^\*\*|\*\*$/g, '')).filter(Boolean)
          : [];
        continue;
      }

      // Additional
      const additionalHeaderMatch = trimmed.match(/^(?:\*|\-)?\s*(?:\*\*)?Additional(?:\*\*)?\s*:\s*(.*)$/i);
      if (additionalHeaderMatch) {
        currentField = 'additional';
        const inlineContent = additionalHeaderMatch[1].replace(/^\*\*|\*\*$/g, '').trim();
        if (inlineContent) {
          additionalLines.push(inlineContent);
        }
        continue;
      }

      // Example
      const exampleMatch = trimmed.match(/^(?:\*|\-)?\s*(?:\*\*)?Example(?:\*\*)?\s*:\s*(.+)$/i);
      if (exampleMatch) {
        currentField = 'example';
        currentWord.example = exampleMatch[1].replace(/^\*\*|\*\*$/g, '').trim();
        continue;
      }

      // Continuation lines
      if (currentField === 'additional' || /^\s*\([^)]+\):/.test(trimmed)) {
        additionalLines.push(trimmed);
        continue;
      }

      if (currentField === 'meaning' && currentWord.meaning) {
        currentWord.meaning += ' ' + trimmed;
        continue;
      }

      if (currentField === 'example' && currentWord.example) {
        currentWord.example += ' ' + trimmed;
        continue;
      }
    }
  }

  finalizeCurrentWord();

  return {
    headerTitle,
    words,
    rawMarkdown: cleanText,
    truncationNote,
  };
}

export function formatVocabToCleanText(
  data: {
    words: Array<{
      word: string;
      pos?: string;
      meaning?: string;
      synonyms?: string[];
      antonyms?: string[];
      additional?: string;
      additionalGroups?: Array<{ theme: string; terms: string }>;
      example?: string;
      mnemonic?: string;
    }>;
    title?: string;
  }
): string {
  const lines: string[] = ['Core Vocabularies & Additional Words', ''];

  for (const item of data.words) {
    if (!item.word || !item.word.trim()) continue;

    const posFormatted = item.pos
      ? item.pos.charAt(0).toUpperCase() + item.pos.slice(1).toLowerCase()
      : 'Noun';

    lines.push(`${item.word.trim()} (${posFormatted})`);

    if (item.meaning && item.meaning.trim()) {
      lines.push(`Meaning: ${item.meaning.trim()}`);
    }

    if (item.synonyms && item.synonyms.length > 0) {
      lines.push(`Synonyms: ${item.synonyms.join(', ')}`);
    }

    if (item.antonyms && item.antonyms.length > 0) {
      lines.push(`Antonyms: ${item.antonyms.join(', ')}`);
    }

    if (item.additionalGroups && item.additionalGroups.length > 0) {
      lines.push(`Additional:`);
      for (const group of item.additionalGroups) {
        lines.push(`(${group.theme}): ${group.terms}`);
      }
    } else if (item.additional && item.additional.trim()) {
      lines.push(`Additional:`);
      const addLines = item.additional.split('\n');
      for (const addLine of addLines) {
        if (addLine.trim()) {
          lines.push(`${addLine.trim()}`);
        }
      }
    }

    if (item.example && item.example.trim()) {
      lines.push(`Example: ${item.example.trim()}`);
    }

    lines.push('');
  }

  return lines.join('\n').trim();
}

/**
 * Converts structured vocabulary objects back to the strict Markdown blueprint format.
 */
export function formatVocabToMarkdown(
  data: {
    words: Array<{
      word: string;
      pos?: string;
      meaning?: string;
      synonyms?: string[];
      antonyms?: string[];
      additional?: string;
      additionalGroups?: Array<{ theme: string; terms: string }>;
      example?: string;
      mnemonic?: string;
    }>;
    title?: string;
  }
): string {
  const lines: string[] = ['#### **Core Vocabularies & Additional Words**', ''];

  for (const item of data.words) {
    if (!item.word || !item.word.trim()) continue;

    const posFormatted = item.pos
      ? item.pos.charAt(0).toUpperCase() + item.pos.slice(1).toLowerCase()
      : 'Noun';

    lines.push(`* **${item.word.trim()} (${posFormatted})**`);

    if (item.meaning && item.meaning.trim()) {
      lines.push(`    * **Meaning:** ${item.meaning.trim()}`);
    }

    if (item.synonyms && item.synonyms.length > 0) {
      lines.push(`    * **Synonyms:** ${item.synonyms.join(', ')}`);
    }

    if (item.antonyms && item.antonyms.length > 0) {
      lines.push(`    * **Antonyms:** ${item.antonyms.join(', ')}`);
    }

    // Additional themes
    if (item.additionalGroups && item.additionalGroups.length > 0) {
      lines.push(`    * **Additional:**`);
      for (const group of item.additionalGroups) {
        lines.push(`        (${group.theme}): ${group.terms}`);
      }
    } else if (item.additional && item.additional.trim()) {
      lines.push(`    * **Additional:**`);
      const addLines = item.additional.split('\n');
      for (const addLine of addLines) {
        if (addLine.trim()) {
          lines.push(`        ${addLine.trim()}`);
        }
      }
    }

    if (item.example && item.example.trim()) {
      lines.push(`    * **Example:** ${item.example.trim()}`);
    }

    lines.push('');
  }

  return lines.join('\n').trim();
}
